    with pipe('rpcinfo', '-p') as f:
        for line in f:
            # line is 'program vers proto port service'
            parts = line.split()
            if not parts or parts[0] == 'program':
                continue
            proto = parts[2]
            port = parts[3]
            program = parts[4] if len(parts) > 4 else '-'
            yield NetStatTuple(proto, None, int(port), None, program)


